// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length == v.length && _tos.length > 0);
        // Bound values to avoid overflow and ensure multiplication doesn't overflow
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, 1e15);
        }
        uint256 balanceBefore = address(c).balance;
        // The original only allows msg.sender == 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        c.transfer(_tos, v);
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceBefore == balanceAfter);
    }
}

